53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Maximum number of owners allowed to be registered in a single city. A new owner
64	     * whose city already holds this many owners is rejected as a conflict.
65	     */
66	    private static final long MAX_OWNERS_PER_CITY = 50;
67	
68	    /**
69	     * Maximum number of owners allowed to be registered in a single day. Once this many
70	     * owners already carry today's registration date, a further create is rejected as
71	     * too many requests.
72	     */
73	    private static final long MAX_OWNERS_PER_DAY = 100;
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final EmailNormalizer emailNormalizer;
86	
87	    private final AddressNormalizer addressNormalizer;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper,
93	                                 TelephoneNormalizer telephoneNormalizer,
94	                                 EmailNormalizer emailNormalizer,
95	                                 AddressNormalizer addressNormalizer) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	        this.telephoneNormalizer = telephoneNormalizer;
101	        this.emailNormalizer = emailNormalizer;
102	        this.addressNormalizer = addressNormalizer;
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
108	        Collection<Owner> owners;
109	        if (lastName != null) {
110	            owners = this.clinicService.findOwnerByLastName(lastName);
111	        } else {
112	            owners = this.clinicService.findAllOwners();
113	        }
114	        if (owners.isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
123	        Owner owner = this.clinicService.findOwnerById(ownerId);
124	        if (owner == null) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
133	        HttpHeaders headers = new HttpHeaders();
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        String address = addressNormalizer.normalize(owner.getAddress());
136	        if (addressNormalizer.isBlank(address)) {
137	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
138	        }
139	        owner.setAddress(address);
140	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
141	        if (e164Telephone.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
143	        }
144	        String telephone = e164Telephone.get();
145	        String email = emailNormalizer.normalize(owner.getEmail());
146	        if (email != null && !emailNormalizer.isValid(email)) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        LocalDate registrationDate = BusinessDay.rollForward(
150	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate());
151	        owner.setRegistrationDate(registrationDate);
152	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
153	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
154	        }
155	        if (clinicService.existsOwnerByTelephone(telephone)) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
159	            return new ResponseEntity<>(HttpStatus.CONFLICT);
160	        }
161	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
162	        if (!sharesHousehold
163	            && clinicService.existsOwnerByLastNameAndAddress(owner.getLastName(), owner.getAddress())) {
164	            return new ResponseEntity<>(HttpStatus.CONFLICT);
165	        }
166	        owner.setTelephone(telephone);
167	        owner.setEmail(email);
168	        if (sharesHousehold) {
169	            clinicService.shareHousehold(owner);
170	        }
171	        this.clinicService.saveOwner(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
186	        if (e164Telephone.isEmpty()) {
187	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	        }
189	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
190	        if (email != null && !emailNormalizer.isValid(email)) {
191	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
192	        }
193	        currentOwner.setAddress(ownerFieldsDto.getAddress());
194	        currentOwner.setCity(ownerFieldsDto.getCity());
195	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
196	        currentOwner.setLastName(ownerFieldsDto.getLastName());
197	        currentOwner.setTelephone(e164Telephone.get());
198	        currentOwner.setEmail(email);
199	        this.clinicService.saveOwner(currentOwner);
200	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Transactional
205	    @Override
206	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        this.clinicService.deleteOwner(owner);
212	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        HttpHeaders headers = new HttpHeaders();
223	        Pet pet = petMapper.toPet(petFieldsDto);
224	        owner.setId(ownerId);
225	        pet.setOwner(owner);
226	        pet.getType().setName(null);
227	        this.clinicService.savePet(pet);
228	        PetDto petDto = petMapper.toPetDto(pet);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
230	            .buildAndExpand(pet.getId()).toUri());
231	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner != null) {
239	            Pet currentPet = this.clinicService.findPetById(petId);
240	            if (currentPet != null) {
241	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
242	                currentPet.setName(petFieldsDto.getName());
243	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
244	                this.clinicService.savePet(currentPet);
245	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
246	            }
247	        }
248	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
254	        HttpHeaders headers = new HttpHeaders();
255	        Visit visit = visitMapper.toVisit(visitFieldsDto);
256	        Pet pet = new Pet();
257	        pet.setId(petId);
258	        visit.setPet(pet);
259	        this.clinicService.saveVisit(visit);
260	        VisitDto visitDto = visitMapper.toVisitDto(visit);
261	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
262	            .buildAndExpand(visit.getId()).toUri());
263	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
264	    }
265	
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner != null) {
272	            Pet pet = owner.getPet(petId);
273	            if (pet != null) {
274	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
275	            }
276	        }
277	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	    }
279	}
