16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
135	     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
136	     * Derived from the owner's own fields, so it stays consistent with them.
137	     */
138	    @Transient
139	    public String getMembershipNumber() {
140	        if (this.customerCode == null || this.registrationDate == null) {
141	            return null;
142	        }
143	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
144	    }
145	
146	    /**
147	     * The owner's membership tier: {@code "SILVER"} for a unique owner (namesake
148	     * count of zero) who has an email on file, and {@code "BRONZE"} otherwise.
149	     * Derived from the owner's own fields, so it stays consistent with them.
150	     */
151	    @Transient
152	    public String getMembershipTier() {
153	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
154	        boolean hasEmail = this.email != null && !this.email.isEmpty();
155	        return unique && hasEmail ? "SILVER" : "BRONZE";
156	    }
157	
158	    /**
159	     * The owner's locality: the canonical region derived from the city via the fixed
160	     * {@link CityRegionTable}, or {@code "UNKNOWN"} when the city is not in the table.
161	     * Derived from the owner's own city, so it stays consistent with it.
162	     */
163	    @Transient
164	    public String getLocality() {
165	        return CityRegionTable.regionFor(this.city);
166	    }
167	
168	    /**
169	     * Normalize the registration date before persisting: default it to the server's
170	     * current date when none was supplied, then roll it forward onto a business day so
171	     * every newly persisted owner is registered on a weekday.
172	     */
173	    @PrePersist
174	    void normalizeRegistrationDate() {
175	        if (this.registrationDate == null) {
176	            this.registrationDate = LocalDate.now();
177	        }
178	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
179	    }
180	
181	    protected Set<Pet> getPetsInternal() {
182	        if (this.pets == null) {
183	            this.pets = new HashSet<>();
184	        }
185	        return this.pets;
186	    }
187	
188	    protected void setPetsInternal(Set<Pet> pets) {
189	        this.pets = pets;
190	    }
191	
192	    public List<Pet> getPets() {
193	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
194	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
195	        return Collections.unmodifiableList(sortedPets);
196	    }
197	
198	    public void setPets(List<Pet> pets) {
199	        this.pets = new HashSet<>(pets);
200	    }
201	
202	    public void addPet(Pet pet) {
203	        getPetsInternal().add(pet);
204	        pet.setOwner(this);
205	    }
206	
207	    /**
208	     * Return the Pet with the given name, or null if none found for this Owner.
209	     *
210	     * @param name to test
211	     * @return true if pet name is already in use
212	     */
213	    public Pet getPet(String name) {
214	        return getPet(name, false);
215	    }
216	
217	    /**
218	     * Return the Pet with the given name, or null if none found for this Owner.
219	     *
220	     * @param name to test
221	     * @return true if pet name is already in use
222	     */
223	    public Pet getPet(String name, boolean ignoreNew) {
224	        name = name.toLowerCase();
225	        for (Pet pet : getPetsInternal()) {
226	            if (!ignoreNew || !pet.isNew()) {
227	                String compName = pet.getName();
228	                compName = compName.toLowerCase();
229	                if (compName.equals(name)) {
230	                    return pet;
231	                }
232	            }
233	        }
234	        return null;
235	    }
236	
237	    public Pet getPet(Integer petId) {
238	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
239	    }
240	
241	    @Override
242	    public String toString() {
243	        return new ToStringCreator(this)
244	
245	            .append("id", this.getId())
246	            .append("new", this.isNew())
247	            .append("lastName", this.getLastName())
248	            .append("firstName", this.getFirstName())
249	            .append("address", this.address)
250	            .append("city", this.city)
251	            .append("telephone", this.telephone)
252	            .toString();
253	    }
254	}
