19	import java.util.Locale;
20	import java.util.Map;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes an owner's postal address into a single canonical form so that
26	 * addresses that differ only cosmetically are stored, returned and compared
27	 * identically.
28	 *
29	 * <p>Normalization trims and collapses each run of whitespace to a single space,
30	 * upper-cases the value and expands common street-type abbreviations
31	 * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). An address
32	 * that is blank after normalization carries no meaning and is rejected by the
33	 * required-field check.
34	 */
35	@Component
36	public class AddressNormalizer {
37	
38	    /** Whole-word street-type abbreviations expanded to their canonical form. */
39	    private static final Map<String, String> ABBREVIATIONS = Map.of(
40	        "ST", "STREET",
41	        "RD", "ROAD",
42	        "AVE", "AVENUE");
43	
44	    /**
45	     * Convert a raw address into its canonical normalized form.
46	     *
47	     * @param address the raw address value (may be {@code null})
48	     * @return the normalized address, or {@code null} if {@code address} is {@code null}
49	     */
50	    public String normalize(String address) {
51	        if (address == null) {
52	            return null;
53	        }
54	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
55	        if (collapsed.isEmpty()) {
56	            return "";
57	        }
58	        String[] words = collapsed.split(" ");
59	        for (int i = 0; i < words.length; i++) {
60	            words[i] = ABBREVIATIONS.getOrDefault(words[i], words[i]);
61	        }
62	        return String.join(" ", words);
63	    }
64	
65	    /**
66	     * @param address an address value (typically already normalized)
67	     * @return {@code true} if it carries meaningful, non-blank content
68	     */
69	    public boolean isBlank(String address) {
70	        return address == null || address.isBlank();
71	    }
72	}
