297	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
298	        // Backfill the existing members so the whole household carries one shared id.
299	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
300	            .filter(member -> !householdId.equals(member.getHouseholdId()))
301	            .forEach(member -> {
302	                member.setHouseholdId(householdId);
303	                ownerRepository.save(member);
304	            });
305	        owner.setHouseholdId(householdId);
306	        return householdId;
