314	        String householdId = householdIdGenerator.generate(lastName, address);
315	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
316	            .filter(owner -> householdId.equals(
317	                householdIdGenerator.generate(owner.getLastName(), owner.getAddress())))
318	            .toList();
