16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.stereotype.Component;
19	
20	/**
21	 * Builds an owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
22	 * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased
23	 * first three letters of the last name and NNNN is a per-city 4-digit zero-padded
24	 * sequence.
25	 */
26	@Component
27	public class CustomerCodeGenerator {
28	
29	    private static final int PREFIX_LENGTH = 3;
30	
31	    /**
32	     * Build the customer code for a new owner.
33	     *
34	     * @param city                   the owner's city
35	     * @param lastName               the owner's last name
36	     * @param existingCityOwnerCount the number of owners already registered in that city;
37	     *                               the assigned sequence is one more than this value
38	     * @return the formatted customer code, e.g. {@code "LON-SMI-0007"}
39	     */
40	    public String generate(String city, String lastName, long existingCityOwnerCount) {
41	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), existingCityOwnerCount + 1);
42	    }
43	
44	    private String prefix(String value) {
45	        return value.substring(0, Math.min(PREFIX_LENGTH, value.length())).toUpperCase();
46	    }
47	}
